<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Focus Stopwatch','description'=>'A simple stopwatch for focused work sessions.','url'=>'https://smarttoolz.in/tools/focus-stopwatch/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Focus Stopwatch</h1><p>Track elapsed time with start, pause and reset.</p></section><section class="tool-workspace"><div class="tool-panel"><div id="o" style="font-size:40px;font-weight:800">00:00.000</div><button id="s" class="tool-btn">Start</button><button id="r" class="tool-btn">Reset</button></div></section></main><script>let t=0,id=0,last=0;function draw(){o.textContent=`${String(Math.floor(t/60000)).padStart(2,'0')}:${String(Math.floor(t/1000)%60).padStart(2,'0')}.${String(t%1000).padStart(3,'0')}`}s.onclick=()=>{if(id){clearInterval(id);id=0;s.textContent='Start'}else{last=Date.now();id=setInterval(()=>{t+=Date.now()-last;last=Date.now();draw()},20);s.textContent='Pause'}};r.onclick=()=>{clearInterval(id);id=0;t=0;draw();s.textContent='Start'}</script><?php smarttoolz_tool_page_end(); ?>